/// <reference path="../../../src/lib/workflow-defs.d.ts" />

import { appendFileSync } from "node:fs";
import { join } from "node:path";
import {
  promoteAgent,
  discardAgent,
  type GrowthConfig,
} from "../../../src/lib/growth.js";
import {
  runGym,
  listScenarios,
  findLabForks,
  extractScenarios,
  extractAgentFromText,
  agentFromFork,
  extractFMCode,
  extractMethod,
  formatGymResults,
  appendSkipRecord,
  type GymResult,
  LAB_DIR,
  AGENTS_ROOT,
  PROJECT_ROOT,
} from "./gym-helpers.js";

export const name: string = "growth-cycle";

export const description: string =
  "Evidence-based agent improvement. Diagnose a problem (or pick a method " +
  "to learn), fork agent, apply one change, test via gym, record results. " +
  "Pass 'learn:<method>' as the task to run in learning mode (always discards).";

export async function execute(ctx: WorkflowContext): Promise<WorkflowResult> {
  const isLearning = ctx.task.startsWith("learn:");

  // Step 1: Diagnose / Study
  const step1Prompt = isLearning
    ? `Study an improvement method you haven't used before.\n\n` +
      `## Method to Learn\n${ctx.task.slice(6).trim()}\n\n` +
      `## Instructions\n` +
      `1. Read \`agents/coach/knowledge/method-catalog.md\` — find this method's entry.\n` +
      `2. Read documentation and examples related to this method:\n` +
      `   - For skills: read \`agents/shared/skills/\` for examples\n` +
      `   - For workflows: read existing workflows in \`agents/*/workflows/\`\n` +
      `   - For heartbeat steps: read \`agents/*/heartbeat.md\` examples\n` +
      `   - For knowledge files: read \`agents/*/knowledge/\` examples\n` +
      `   - For agent.json: read the agent-loader source for config options\n` +
      `3. Pick a simple gym scenario to test with: \`ls agents/gym/scenarios/\`\n` +
      `4. Pick a target agent (preferably coder — simplest agent).\n` +
      `5. Design a small experiment: what change will you make using this method?\n` +
      `6. Report: what you learned about the method, your experiment plan.`
    : `Diagnose an error pattern and select an improvement method.\n\n` +
      `## Error Pattern\n${ctx.task}\n\n` +
      `## Instructions\n` +
      `1. Read the error examples from the task description above. Identify the behavioral pattern.\n` +
      `2. Read \`agents/coach/knowledge/method-catalog.md\` — understand available methods.\n` +
      `3. Read \`agents/coach/workspace/experiments.jsonl\` (if it exists) — check if this pattern was already tested.\n` +
      `4. Choose ONE method from the catalog that best fits this error pattern.\n` +
      `   - If the catalog has evidence for this pattern → use the proven method.\n` +
      `   - If no evidence → pick the method you think fits best (you'll test it).\n` +
      `5. Identify which agent needs the fix.\n` +
      `6. Identify which gym scenarios can test this fix (check \`agents/gym/scenarios/\` with \`ls\`).\n` +
      `7. Report:\n` +
      `   - Error pattern (FM code + description)\n` +
      `   - Target agent\n` +
      `   - Selected method (from catalog)\n` +
      `   - Why this method (reasoning)\n` +
      `   - Gym scenarios to test against\n` +
      `   - What specifically you'll change`;

  const step1 = await ctx.runAgent("coach", step1Prompt);
  if (step1.status === "error") {
    return ctx.escalate("step 1 failed", { error: step1.error });
  }
  // Interrupted sessions may still have useful partial output — proceed
  // with whatever the agent produced before being cut off.

  // Step 1b: Ceiling-effect gate — run baseline BEFORE forking (JS, no LLM)
  ctx.emit({ type: "step_start", step: "ceiling-gate" });

  const diagnosisText = step1.lastAssistantText ?? "";
  const gateScenarios = extractScenarios(ctx.task + "\n" + diagnosisText);
  const gateAgent = extractAgentFromText(ctx.task + "\n" + diagnosisText);

  if (gateScenarios.length === 0 || !gateAgent) {
    // Can't run gate without scenarios/agent — fall through to fork step
    // (the LLM diagnosis didn't mention recognizable scenarios or agents)
    ctx.emit({ type: "step_done", step: "ceiling-gate" } as any);
  } else {
    const gateResults: GymResult[] = [];
    let anyFails = false;
    for (const scenario of gateScenarios) {
      const result = runGym(scenario, gateAgent);
      gateResults.push(result);
      if (!result.passed) anyFails = true;
    }

    const gateReport = gateResults
      .map(r => `- ${r.scenario}: ${r.passed ? "PASS" : "FAIL"} (${r.checks.filter(c => c.passed).length}/${r.checks.length})`)
      .join("\n");

    ctx.emit({ type: "step_done", step: "ceiling-gate" } as any);

    if (!anyFails) {
      // Ceiling effect — all pass, skip the experiment
      appendSkipRecord(gateAgent, gateScenarios, diagnosisText);

      return ctx.done(
        `Growth cycle SKIPPED (ceiling-effect gate).\n\n` +
        `## Diagnosis\n${diagnosisText}\n\n` +
        `## Baseline Gate Results\n${gateReport}\n\n` +
        `All scenarios pass at baseline — no room for improvement. ` +
        `Create harder scenarios before retrying this pattern.`
      );
    }
  }

  // Step 2: Fork and apply
  const patch = await ctx.runAgent("coach",
    `Fork the target agent and apply exactly ONE improvement method.\n\n` +
    `## ${isLearning ? "Study Results" : "Diagnosis"}\n${ctx.summarize(step1)}\n\n` +
    `## Instructions\n` +
    `1. Fork the target agent: \`fork_agent({ source: "<agent>", dest: "<agent>-<experiment>" })\`\n` +
    `2. Apply the selected method to the fork. Be specific and minimal:\n` +
    `   - SOUL guard → add 5-15 lines max\n` +
    `   - Heartbeat step → add one numbered step\n` +
    `   - Skill → create one SKILL.md file\n` +
    `   - Workflow → create one workflow .ts file\n` +
    `   - Knowledge → create one .md file\n` +
    `3. Read back the changed file(s) to confirm the edit worked.\n` +
    `4. Do NOT apply multiple methods — one method per experiment.\n` +
    `5. Report: what you changed, the fork name, and the file(s) modified.\n\n` +
    `IMPORTANT: The fork lives in agents/.lab/<fork-name>/. Verify it exists.\n\n` +
    `⚠️ Do NOT delete or discard the fork — even if you discover the baseline already passes. ` +
    `The workflow manages fork lifecycle (promote/discard) automatically after testing.`
  );
  if (patch.status === "error") {
    return ctx.escalate("fork/patch failed", { error: patch.error });
  }


  // Step 3: Gym test (direct script execution — no LLM session needed)
  ctx.emit({ type: "step_start", step: "gym-test" });

  // Discover fork from .lab/ directory (Step 2 should have created one)
  const forks = findLabForks();
  const patchText = patch.lastAssistantText ?? "";
  // Find the fork that was just created — prefer one mentioned in patch output
  let forkName = forks.find(f => patchText.includes(f)) ?? forks[0];
  if (!forkName) {
    // Check if coach found ceiling effect and discarded (common pattern)
    const lowerPatch = patchText.toLowerCase();
    const ceilingDiscarded = lowerPatch.includes("discard") || lowerPatch.includes("ceiling") ||
      lowerPatch.includes("baseline") && lowerPatch.includes("pass");

    if (ceilingDiscarded) {
      return ctx.done(
        `Growth cycle ended — coach found ceiling effect during patch step.\n\n` +
        `## Patch Step Output\n${patchText.slice(0, 1000)}\n\n` +
        `The baseline already passes. Fork was discarded by coach. ` +
        `Consider creating harder scenarios for this pattern.`
      );
    }

    return ctx.escalate("No fork found in agents/.lab/ after patch step", {
      labDir: LAB_DIR,
      patchOutput: patchText.slice(0, 500),
    });
  }

  // Extract agent name from the fork
  const agentName = agentFromFork(forkName);

  // Extract scenarios from task description + Step 1 + patch output.
  // Include ctx.task so the target scenario from the original request is always found —
  // previous bug: LLM outputs sometimes omit the scenario name, causing fallback to
  // alphabetically-first scenarios (which are unrelated to the target).
  const combinedText =
    ctx.task + "\n" +
    (step1.lastAssistantText ?? "") + "\n" +
    patchText;
  let scenarios = extractScenarios(combinedText);
  if (scenarios.length === 0) {
    // Fallback: use first 3 scenarios to keep runtime reasonable
    scenarios = listScenarios().slice(0, 3);
  }

  // Run baseline tests
  const baselineResults: GymResult[] = [];
  for (const scenario of scenarios) {
    baselineResults.push(runGym(scenario, agentName));
  }

  // Run patched (fork) tests
  const patchedResults: GymResult[] = [];
  for (const scenario of scenarios) {
    patchedResults.push(runGym(scenario, agentName, forkName));
  }

  const gymResultsText = formatGymResults(baselineResults, patchedResults, forkName);

  ctx.emit({ type: "step_done", step: "gym-test" });

  // Step 4: Record and decide (pure JS — no LLM session needed)
  // Compare pass counts to determine promote/discard
  const baselinePassed = baselineResults.filter(r => r.passed).length;
  const patchedPassed = patchedResults.filter(r => r.passed).length;
  const improved = patchedPassed > baselinePassed;

  // In learning mode, always discard. In fix mode, promote only if improved.
  const decision = isLearning ? "discard" as const : (improved ? "promote" as const : "discard" as const);
  const reason = isLearning
    ? "learning mode — always discard after recording observations"
    : improved
      ? `patched passed ${patchedPassed}/${scenarios.length} vs baseline ${baselinePassed}/${scenarios.length}`
      : patchedPassed === baselinePassed
        ? `no improvement — patched ${patchedPassed}/${scenarios.length} same as baseline`
        : `regression — patched ${patchedPassed}/${scenarios.length} worse than baseline ${baselinePassed}/${scenarios.length}`;

  // Execute promote/discard via growth.ts pure functions
  const growthConfig: GrowthConfig = { agentsRoot: AGENTS_ROOT };
  let decisionReport: string;

  try {
    if (decision === "promote") {
      const result = promoteAgent(growthConfig, forkName, agentName);
      decisionReport = `PROMOTED "${forkName}" → "${agentName}". Copied: ${result.promoted.join(", ")}. Reason: ${reason}`;
    } else {
      discardAgent(growthConfig, forkName);
      decisionReport = `DISCARDED "${forkName}". Reason: ${reason}`;
    }
  } catch (err: any) {
    decisionReport = `${decision.toUpperCase()} attempted but failed: ${err.message}. Reason: ${reason}`;
  }

  // Record to experiments.jsonl
  const diagText = step1.lastAssistantText ?? "";
  const experimentEntry = isLearning
    ? {
        timestamp: new Date().toISOString(),
        type: "learn-method",
        method: extractMethod(diagText),
        agent: agentName,
        scenarios: scenarios.map(s => {
          const b = baselineResults.find(r => r.scenario === s);
          const p = patchedResults.find(r => r.scenario === s);
          return { name: s, baseline: b?.passed ?? false, patched: p?.passed ?? false };
        }),
        decision,
        reason,
      }
    : {
        timestamp: new Date().toISOString(),
        error_pattern: extractFMCode(diagText),
        agent: agentName,
        method: extractMethod(diagText),
        scenarios: scenarios.map(s => {
          const b = baselineResults.find(r => r.scenario === s);
          const p = patchedResults.find(r => r.scenario === s);
          return { name: s, baseline: b?.passed ?? false, patched: p?.passed ?? false };
        }),
        decision,
        reason,
      };

  const experimentsPath = join(PROJECT_ROOT, "agents/coach/workspace/experiments.jsonl");
  appendFileSync(experimentsPath, JSON.stringify(experimentEntry) + "\n");

  // For learning mode, still use a lightweight LLM session to update method-catalog.md
  // (this is the only part that benefits from LLM judgment — cataloging observations)
  let catalogUpdate = "";
  if (isLearning) {
    const catalogPrompt =
      `Update the method catalog with what you learned.\n\n` +
      `## Test Results Summary\n` +
      `Baseline passed: ${baselinePassed}/${scenarios.length}, Patched passed: ${patchedPassed}/${scenarios.length}\n` +
      `Decision: ${decision} (${reason})\n\n` +
      `## Instructions\n` +
      `1. Read \`agents/coach/knowledge/method-catalog.md\`\n` +
      `2. Find the entry for method: ${extractMethod(diagText)}\n` +
      `3. Update its Evidence section with these concrete observations\n` +
      `4. Change Status from "untested" to "tested" with today's date\n` +
      `5. Report what you updated.`;

    const catalogResult = await ctx.runAgent("coach", catalogPrompt);
    catalogUpdate = catalogResult.lastAssistantText ?? "(catalog update session failed)";
  }

  return ctx.done(
    `Growth cycle completed (${isLearning ? "learning" : "fix"} mode).\n\n` +
    `## ${isLearning ? "Study" : "Diagnosis"}\n${step1.lastAssistantText}\n\n` +
    `## Results\n${gymResultsText}\n\n` +
    `## Decision (automated)\n${decisionReport}\n` +
    `Recorded to experiments.jsonl.` +
    (catalogUpdate ? `\n\n## Catalog Update\n${catalogUpdate}` : "")
  );
}

/// <reference path="../../../src/workflow-defs.d.ts" />

import { writeFileSync, appendFileSync } from "node:fs";
import { join } from "node:path";
import {
  promoteAgent,
  discardAgent,
  type GrowthConfig,
} from "../../../src/lib/growth.js";
import {
  runGym,
  findLabForks,
  extractScenarios,
  agentFromFork,
  formatGymResults,
  extractFMCode,
  extractMethod,
  type GymResult,
  PROJECT_ROOT,
  AGENTS_ROOT,
} from "./gym-helpers.js";

export const name: string = "training-sprint";

export const description: string =
  "Batch-run multiple growth experiments efficiently. Diagnose several error " +
  "patterns in one session, fork and patch each, run gym tests in parallel, " +
  "then record all results. Use this when Coach has 3+ queued growth targets " +
  "or wants to rapidly learn multiple methods.";

export async function execute(ctx: WorkflowContext): Promise<WorkflowResult> {
  // Step 1: Batch diagnosis — identify multiple experiments to run
  const plan = await ctx.runAgent("coach",
    `Plan a training sprint — identify multiple experiments to run in batch.\n\n` +
    `## Context\n${ctx.task}\n\n` +
    `## Instructions\n` +
    `1. Read \`agents/coach/workspace/todo.md\` — find all growth cycle candidates.\n` +
    `2. Read \`agents/*/ERROR_LOG.jsonl\` — find error patterns worth fixing.\n` +
    `3. Read \`agents/coach/knowledge/method-catalog.md\` — check for untested methods\n` +
    `   AND check for "hypothesis" entries (invented methods) that need testing.\n` +
    `4. Read \`agents/coach/workspace/experiments.jsonl\` — skip patterns already tested.\n` +
    `   For patterns with 2+ failures: try a DIFFERENT method or an invented one.\n` +
    `5. **CEILING-EFFECT GATE (MANDATORY):** For each candidate experiment, run baseline:\n` +
    `   \`test/gym/run-gym.sh <scenario> --agent <agent> --timeout 3\`\n` +
    `   If baseline PASSES all checks → REMOVE that experiment from the plan.\n` +
    `   Only keep experiments where baseline FAILS at least one check.\n` +
    `   If ALL candidates are removed by this gate, your output should be:\n` +
    `   "GATE: ALL SKIPPED — ceiling effect on all candidates. Need harder scenarios."\n` +
    `   This gate prevents wasting ~4 LLM sessions per experiment on zero-improvement cycles.\n` +
    `6. Select 3-5 experiments. For each, specify:\n` +
    `   - Target agent\n` +
    `   - Error pattern (FM code) or method to learn\n` +
    `   - Method to apply (can be a hypothesis from the catalog)\n` +
    `   - Gym scenario(s) to test against (check \`ls agents/gym/scenarios/\`)\n` +
    `   - Fork name (e.g., coder-sprint-1, optimizer-sprint-2)\n` +
    `7. Write the plan to \`agents/coach/workspace/sprint-plan.md\`\n` +
    `8. Report the full plan.`
  );
  if (plan.status === "error") {
    return ctx.escalate("sprint planning failed", { error: plan.error });
  }

  // Check if ceiling-effect gate eliminated all experiments
  const planText = (plan.lastAssistantText || "").toUpperCase();
  if (planText.includes("GATE: ALL SKIPPED") || planText.includes("CEILING EFFECT ON ALL")) {
    // Record skip directly in JS — no LLM session needed for a single JSONL append
    const skipEntry = {
      timestamp: new Date().toISOString(),
      type: "sprint",
      error_pattern: "multiple",
      agent: "multiple",
      method: "N/A",
      scenarios: [],
      decision: "skipped",
      reason: "ceiling-effect gate: all sprint candidates pass baseline",
    };
    appendFileSync(
      join(PROJECT_ROOT, "agents/coach/workspace/experiments.jsonl"),
      JSON.stringify(skipEntry) + "\n",
    );

    return ctx.done(
      `Training sprint SKIPPED (ceiling-effect gate).\n\n` +
      `## Plan\n${plan.lastAssistantText}\n\n` +
      `All candidate experiments pass baseline — no room for improvement. ` +
      `Create harder scenarios before the next sprint.`
    );
  }

  // Step 2: Fork and patch all experiments
  const patch = await ctx.runAgent("coach",
    `Execute all forks and patches from the sprint plan.\n\n` +
    `## Sprint Plan\n${ctx.summarize(plan)}\n\n` +
    `## Instructions\n` +
    `Read \`agents/coach/workspace/sprint-plan.md\` for the full plan.\n\n` +
    `For EACH experiment in the plan:\n` +
    `1. Fork: \`fork_agent({ source: "<agent>", dest: "<fork-name>" })\`\n` +
    `2. Apply ONE method to the fork (SOUL guard, heartbeat step, skill, etc.)\n` +
    `3. Read back the changed file to confirm\n` +
    `4. Move to the next experiment\n\n` +
    `Be efficient — don't over-explain each change. Fork, patch, verify, next.\n` +
    `Report: list of forks created with what was changed in each.`
  );
  if (patch.status === "error") {
    return ctx.escalate("batch forking failed", { error: patch.error });
  }

  // Step 3: Run all gym tests — direct JS execution (no LLM session needed)
  ctx.emit({ type: "step_start", step: "sprint-gym-tests" });

  // Discover forks from .lab/ and match against patch output
  const forks = findLabForks();
  const patchText = patch.lastAssistantText ?? "";
  const planText2 = plan.lastAssistantText ?? "";
  const combinedText = planText2 + "\n" + patchText;

  // Build list of experiments: { forkName, agent, scenarios }
  interface SprintExperiment {
    forkName: string;
    agent: string;
    scenarios: string[];
  }
  const experiments: SprintExperiment[] = [];
  for (const fork of forks) {
    if (patchText.includes(fork)) {
      const agent = agentFromFork(fork);
      const scenarios = extractScenarios(combinedText);
      experiments.push({ forkName: fork, agent, scenarios: scenarios.length > 0 ? scenarios : [] });
    }
  }

  // If no experiments detected from fork matching, try all forks
  if (experiments.length === 0 && forks.length > 0) {
    for (const fork of forks) {
      const agent = agentFromFork(fork);
      const scenarios = extractScenarios(combinedText);
      experiments.push({ forkName: fork, agent, scenarios });
    }
  }

  // Run baseline and patched tests for each experiment
  interface SprintResult {
    fork: string;
    scenario: string;
    baseline: GymResult;
    patched: GymResult;
    delta: number;
  }
  const sprintResults: SprintResult[] = [];
  const resultLines: string[] = ["# Sprint Gym Test Results (automated — no LLM session)\n"];

  for (const exp of experiments) {
    resultLines.push(`## Fork: ${exp.forkName} (agent: ${exp.agent})`);
    if (exp.scenarios.length === 0) {
      resultLines.push("- No scenarios identified for this fork\n");
      continue;
    }

    for (const scenario of exp.scenarios) {
      const baseline = runGym(scenario, exp.agent);
      const patched = runGym(scenario, exp.agent, exp.forkName);
      const bPassed = baseline.checks.filter(c => c.passed).length;
      const pPassed = patched.checks.filter(c => c.passed).length;
      const delta = pPassed - bPassed;

      sprintResults.push({ fork: exp.forkName, scenario, baseline, patched, delta });

      resultLines.push(`- ${scenario}: baseline=${baseline.passed ? "PASS" : "FAIL"} (${bPassed}/${baseline.checks.length}), patched=${patched.passed ? "PASS" : "FAIL"} (${pPassed}/${patched.checks.length}), delta=${delta >= 0 ? "+" : ""}${delta}`);
    }
    resultLines.push("");
  }

  // Write results to file for Step 4 to read
  const resultsText = resultLines.join("\n");
  writeFileSync(join(PROJECT_ROOT, "agents/coach/workspace/sprint-results.md"), resultsText);

  ctx.emit({ type: "step_done", step: "sprint-gym-tests" } as any);

  // Step 4: Record results, promote winners, discard losers (pure JS — no LLM session)
  const growthConfig: GrowthConfig = { agentsRoot: AGENTS_ROOT };
  const decisionLines: string[] = ["# Sprint Decisions (automated — no LLM session)\n"];
  let promoted = 0;
  let discarded = 0;

  // Group results by fork
  const resultsByFork = new Map<string, SprintResult[]>();
  for (const r of sprintResults) {
    const arr = resultsByFork.get(r.fork) ?? [];
    arr.push(r);
    resultsByFork.set(r.fork, arr);
  }

  for (const exp of experiments) {
    const forkResults = resultsByFork.get(exp.forkName) ?? [];
    const baselinePassed = forkResults.filter(r => r.baseline.passed).length;
    const patchedPassed = forkResults.filter(r => r.patched.passed).length;
    const improved = patchedPassed > baselinePassed;
    const decision = improved ? "promote" as const : "discard" as const;
    const reason = improved
      ? `patched ${patchedPassed}/${forkResults.length} vs baseline ${baselinePassed}/${forkResults.length}`
      : patchedPassed === baselinePassed
        ? `no improvement — both ${baselinePassed}/${forkResults.length}`
        : `regression — patched ${patchedPassed}/${forkResults.length} < baseline ${baselinePassed}/${forkResults.length}`;

    // Execute promote or discard
    try {
      if (decision === "promote") {
        const result = promoteAgent(growthConfig, exp.forkName, exp.agent);
        decisionLines.push(`## ${exp.forkName} → PROMOTED`);
        decisionLines.push(`Copied: ${result.promoted.join(", ")}. ${reason}\n`);
        promoted++;
      } else {
        discardAgent(growthConfig, exp.forkName);
        decisionLines.push(`## ${exp.forkName} → DISCARDED`);
        decisionLines.push(`${reason}\n`);
        discarded++;
      }
    } catch (err: any) {
      decisionLines.push(`## ${exp.forkName} → ERROR`);
      decisionLines.push(`${decision} failed: ${err.message}\n`);
    }

    // Record to experiments.jsonl
    const diagText = planText2;  // Use plan text for FM/method extraction
    const entry = {
      timestamp: new Date().toISOString(),
      type: "sprint",
      error_pattern: extractFMCode(diagText),
      agent: exp.agent,
      method: extractMethod(diagText),
      scenarios: forkResults.map(r => ({
        name: r.scenario,
        baseline: r.baseline.passed,
        patched: r.patched.passed,
      })),
      decision,
      reason,
    };
    appendFileSync(
      join(PROJECT_ROOT, "agents/coach/workspace/experiments.jsonl"),
      JSON.stringify(entry) + "\n",
    );
  }

  // Handle experiments with no gym results (no scenarios matched)
  // These weren't processed in the main loop, so discard to clean up
  const processedForks = new Set(
    experiments.filter(e => (resultsByFork.get(e.forkName)?.length ?? 0) > 0).map(e => e.forkName)
  );
  for (const exp of experiments) {
    if (!processedForks.has(exp.forkName)) {
      try {
        discardAgent(growthConfig, exp.forkName);
        decisionLines.push(`## ${exp.forkName} → DISCARDED (no test results)`);
        discarded++;
      } catch {
        // Fork may already have been removed
      }
    }
  }

  const decisionsText = decisionLines.join("\n");

  return ctx.done(
    `Training sprint completed: ${promoted} promoted, ${discarded} discarded.\n\n` +
    `## Plan\n${plan.lastAssistantText}\n\n` +
    `## Results\n${resultsText}\n\n` +
    `## Decisions\n${decisionsText}`
  );
}

/**
 * Shared gym-runner helpers for coach workflows.
 *
 * Extracted from growth-cycle.ts to allow reuse in training-sprint.ts.
 * These replace mechanical LLM sessions that just run gym scripts and
 * parse JSON output.
 */

import { execSync } from "node:child_process";
import { readdirSync, existsSync, appendFileSync } from "node:fs";
import { join, resolve } from "node:path";

export const PROJECT_ROOT = resolve(join(import.meta.dirname ?? ".", "../../.."));
export const AGENTS_ROOT = resolve(process.env["AGENTS_ROOT"] || join(PROJECT_ROOT, "agents"));
export const SCENARIOS_DIR = join(PROJECT_ROOT, "agents/gym/scenarios");
export const LAB_DIR = join(AGENTS_ROOT, ".lab");

export interface GymResult {
  scenario: string;
  agent: string;
  lab_fork: string | null;
  passed: boolean;
  checks: Array<{ name: string; passed: boolean; message?: string }>;
  summary: string;
  agent_status: string;
  duration: string;
